1	package main
2	
3	import (
4		"archive/zip"
5		"bytes"
6		"encoding/json"
7		"fmt"
8		"io"
9		"math/rand"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"testing"
