17	// migrateFixture 建立用于迁移测试的源台账：
18	//   - EQ-A：T0001（报修/派工/领用 P0001/附件 A0001、A0002 同路径/A0002 撤销/
19	//     搬移/关闭）、保养计划与一次完成、未关闭工单 T0002（附件 A0003）。
20	//   - EQ-B：未关闭工单 T0003（附件 A0004）。
21	//   - EQ-C：工单 T0004（不导出）。
22	//   - EQ-D：无工单与附件的资产。
23	//
24	// root 同时容纳源台账目录与原资料目录，测试可整体改名以模拟“源被移走”。
25	type migrateFixture struct {
26		root    string
27		srcDir  string
28		fileDir string
29		files   map[string][]byte // 资料路径 -> 原始内容
30	}
31	
32	func newMigrateFixture(t *testing.T) *migrateFixture {
33		t.Helper()
34		root := filepath.Join(t.TempDir(), "root")
35		srcDir := filepath.Join(root, "src")
36		fileDir := filepath.Join(root, "资料")
37		if err := os.MkdirAll(fileDir, 0o755); err != nil {
38			t.Fatal(err)
39		}
40		s := newStoreAt(t, srcDir)
41		for _, a := range [][3]string{
42			{"EQ-A", "打印机", "一楼"}, {"EQ-B", "空调", "二楼"},
43			{"EQ-C", "投影仪", "三楼"}, {"EQ-D", "饮水机", "四楼"},
44		} {
45			if _, err := s.registerAsset(a[0], a[1], a[2]); err != nil {
46				t.Fatal(err)
47			}
48		}
49		write := func(name, content string) string {
50			p := filepath.Join(fileDir, name)
51			if err := os.WriteFile(p, []byte(content), 0o644); err != nil {
52				t.Fatal(err)
53			}
54			return p
55		}
56		f1 := write("p1.jpg", "资料一内容")
57		f3 := write("p3.jpg", "资料三内容")
58		f4 := write("p4.jpg", "资料四内容")
59	
60		if _, _, err := s.report("EQ-A", "卡纸", "req-a1"); err != nil { // T0001
61			t.Fatal(err)
62		}
63		if _, err := s.assignTicket("T0001", "张三", "首次派工"); err != nil {
64			t.Fatal(err)
65		}
66		if _, err := s.withdrawPart("T0001", "FILTER-01", 2, "更换滤芯"); err != nil { // P0001
67			t.Fatal(err)
68		}
69		if _, err := s.attach("T0001", f1, "卡纸照片"); err != nil { // A0001
70			t.Fatal(err)
71		}
72		if _, err := s.attach("T0001", f1, "同路径另一角度"); err != nil { // A0002
73			t.Fatal(err)
74		}
75		if _, err := s.revokeAttachment("A0002", "照片拍错设备"); err != nil {
76			t.Fatal(err)
77		}
78		if _, _, err := s.relocateAsset("EQ-A", "二楼", "移送维修区"); err != nil {
79			t.Fatal(err)
80		}
81		if _, _, err := s.closeTicket("T0001", "已更换搓纸轮"); err != nil {
82			t.Fatal(err)
83		}
84		if _, err := s.createPlan("EQ-A", "更换滤芯", "2026-11-01", 90); err != nil {
85			t.Fatal(err)
86		}
87		if _, _, _, err := s.completePlan("EQ-A", "2026-11-01", "2026-11-02", "已更换滤芯"); err != nil {
88			t.Fatal(err)
89		}
90		if _, _, err := s.report("EQ-A", "无法开机", "req-a2"); err != nil { // T0002
91			t.Fatal(err)
92		}
93		if _, err := s.attach("T0002", f3, "电源照片"); err != nil { // A0003
94			t.Fatal(err)
95		}
96		if _, _, err := s.report("EQ-B", "不制冷", "req-b1"); err != nil { // T0003
97			t.Fatal(err)
98		}
99		if _, err := s.attach("T0003", f4, "管路照片"); err != nil { // A0004
100			t.Fatal(err)
101		}
102		if _, _, err := s.report("EQ-C", "漏氟", "req-c1"); err != nil { // T0004，不导出
103			t.Fatal(err)
104		}
105		mustSave(t, s)
106		return &migrateFixture{
107			root:    root,
108			srcDir:  srcDir,
109			fileDir: fileDir,
110			files: map[string][]byte{
111				f1: []byte("资料一内容"),
112				f3: []byte("资料三内容"),
113				f4: []byte("资料四内容"),
114			},
115		}
116	}
