118	// 导出后还原：资料脱离源目录仍可读取；关联路径（含撤销履历）同步替换；
119	// 编号、计数器、报修地点、位置起点、保养方案段与完成、请求绑定保持；
120	// 已撤销索引仍撤销；重载、查询、请求重放及后续维修、保养、搬移、编号延续
121	// 按原规则运行。
122	func TestMigrateExportRestoreRoundTrip(t *testing.T) {
123		fx := newMigrateFixture(t)
124		pkg := filepath.Join(t.TempDir(), "eq-a.zip")
125	
126		// 重复编号按一项处理；导出前源台账字节留档。
127		srcBefore := readFileBytes(t, fx.srcDir)
128		out, err := exportPackage(fx.srcDir, pkg, []string{"EQ-A", "EQ-B", "EQ-D", "EQ-A"})
129		if err != nil {
130			t.Fatalf("导出失败: %v", err)
131		}
132		if len(out.assetIDs) != 3 || out.attachments != 4 {
133			t.Fatalf("导出摘要不符: %+v", out)
134		}
135		if string(readFileBytes(t, fx.srcDir)) != string(srcBefore) {
136			t.Fatal("导出不应修改源台账")
137		}
138		pkgBefore, err := os.ReadFile(pkg)
139		if err != nil {
140			t.Fatal(err)
141		}
142	
143		// 还原前整体移走源根目录（台账与原资料一起消失）：证明还原不访问外部资料。
144		moved := fx.root + "-moved"
145		if err := os.Rename(fx.root, moved); err != nil {
146			t.Fatal(err)
147		}
148		for p := range fx.files {
149			if _, err := os.Lstat(p); err == nil {
150				t.Fatalf("原资料 %s 应已随源目录移走", p)
151			}
152		}
153		target := filepath.Join(t.TempDir(), "restored")
154		r, err := restorePackage(pkg, target)
155		if err != nil {
156			t.Fatalf("还原失败: %v", err)
157		}
158		if r.assets != 3 || r.attachments != 4 {
159			t.Fatalf("还原摘要不符: %+v", r)
160		}
161		if got, _ := os.ReadFile(pkg); string(got) != string(pkgBefore) {
162			t.Fatal("还原不应修改迁移包")
163		}
164	
165		// 目标目录结构：台账 + 资料目录，两项。
166		entries, err := os.ReadDir(target)
167		if err != nil {
168			t.Fatal(err)
169		}
170		if len(entries) != 2 {
171			t.Fatalf("目标目录应只有台账与资料目录，得到 %v", entries)
172		}
173		s, err := openStore(target)
174		if err != nil {
175			t.Fatalf("还原后台账应可加载: %v", err)
176		}
177		if s.findAsset("EQ-C") != nil || s.findRequest("req-c1") != nil || s.findTicket("T0004") != nil {
178			t.Fatal("未选择的 EQ-C/T0004/req-c1 不应进入迁移包")
179		}
180		if s.data.NextTicketSeq != 5 || s.data.NextPartSeq != 2 || s.data.NextAttachSeq != 5 {
181			t.Fatalf("原计数器应保持，得到 ticket=%d part=%d attach=%d",
182				s.data.NextTicketSeq, s.data.NextPartSeq, s.data.NextAttachSeq)
183		}
184		// 位置起点、当前位置与报修地点保持。
185		a := s.findAsset("EQ-A")
186		if a == nil || a.Location != "二楼" || a.Status != statusRepairing {
187			t.Fatalf("EQ-A 当前位置与状态不符: %+v", a)
188		}
189		if t1 := s.findTicket("T0001"); t1 == nil || t1.ReportLocation != "一楼" ||
190			t1.Status != ticketClosed || t1.Result != "已更换搓纸轮" || t1.Assignee != "张三" {
191			t.Fatalf("T0001 报修地点与业务内容不符: %+v", t1)
192		}
193		if t2 := s.findTicket("T0002"); t2 == nil || t2.ReportLocation != "二楼" {
194			t.Fatalf("T0002 报修地点应为二楼: %+v", t2)
195		}
196		// 保养计划与下一到期日保持。
197		plan := s.findPlan("EQ-A")
198		if plan == nil || plan.Content != "更换滤芯" || plan.IntervalDays != 90 || plan.NextDue != "2027-01-30" {
199			t.Fatalf("保养计划与下一到期日应保持，得到 %+v", plan)
200		}
201		// 全部附件路径都已替换为目标内副本的绝对路径，且内容与原资料一致；
202		// 同路径的两条索引各为独立副本；已撤销索引仍撤销且资料仍在。
203		rawLedger, err := os.ReadFile(filepath.Join(target, dataFileName))
204		if err != nil {
205			t.Fatal(err)
206		}
207		if strings.Contains(string(rawLedger), "资料") && strings.Contains(string(rawLedger), fx.fileDir) {
208			t.Fatalf("台账中不应残留源资料目录路径 %s", fx.fileDir)
209		}
210		if strings.Contains(string(rawLedger), fx.fileDir) {
211			t.Fatalf("台账中不应残留源资料的绝对路径 %s", fx.fileDir)
212		}
213		wantContent := map[string]string{
214			"A0001": "资料一内容", "A0002": "资料一内容",
215			"A0003": "资料三内容", "A0004": "资料四内容",
216		}
217		paths := map[string]string{}
218		for _, id := range []string{"A0001", "A0002", "A0003", "A0004"} {
219			att := s.findAttachment(id)
220			if att == nil {
221				t.Fatalf("附件 %s 应存在", id)
222			}
223			if filepath.Dir(att.Path) != filepath.Join(target, restoreAttachDir) || !filepath.IsAbs(att.Path) {
224				t.Fatalf("附件 %s 路径应为目标内副本绝对路径，得到 %s", id, att.Path)
225			}
226			got, rerr := os.ReadFile(att.Path)
227			if rerr != nil || string(got) != wantContent[id] {
228				t.Fatalf("附件 %s 副本内容不符: %v %q", id, rerr, got)
229			}
230			paths[id] = att.Path
231			// 登记与撤销履历中的路径也已同步替换。
232			var found int
233			for _, e := range s.data.Events {
234				if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) && e.AttachmentID == id {
235					if e.Path != att.Path {
236						t.Fatalf("附件 %s 履历路径 %s 未同步为 %s", id, e.Path, att.Path)
237					}
238					found++
239				}
240			}
241			if found == 0 {
242				t.Fatalf("附件 %s 缺少登记/撤销履历", id)
243			}
244		}
245		if a2 := s.findAttachment("A0002"); a2 == nil || !a2.Revoked || a2.RevokeReason != "照片拍错设备" {
246			t.Fatalf("A0002 应保持撤销: %+v", a2)
247		}
248		if paths["A0001"] == paths["A0002"] {
249			t.Fatal("同路径的两条索引在目标内应保持为各自独立的副本")
250		}
251	
252		// 后续业务按原规则运行：请求重放、撤销保养完成、领用、新登记、搬移、编号延续。
253		if tk, replayed, err := s.report("EQ-A", "卡纸", "req-a1"); err != nil || !replayed || tk.ID != "T0001" {
254			t.Fatalf("原请求重放应返回 T0001: %v %+v", err, tk)
255		}
256		var doneSeq int
257		for _, e := range s.data.Events {
258			if e.Kind == eventPlanDone {
259				doneSeq = e.Seq
260			}
261		}
262		if doneSeq == 0 {
263			t.Fatal("应能找到保养完成履历")
264		}
265		if _, _, err := s.revokeCompletion("EQ-A", doneSeq, "误登记"); err != nil {
266			t.Fatalf("还原后应可按原序号撤销保养完成: %v", err)
267		}
268		p, err := s.withdrawPart("T0002", "FILTER-02", 1, "维修领用")
269		if err != nil || p.ID != "P0002" {
270			t.Fatalf("编号延续应分配 P0002: %v %+v", err, p)
271		}
272		newFile := filepath.Join(t.TempDir(), "new.jpg")
273		if err := os.WriteFile(newFile, []byte("新资料"), 0o644); err != nil {
274			t.Fatal(err)
275		}
276		na, err := s.attach("T0002", newFile, "补充资料")
277		if err != nil || na.ID != "A0005" {
278			t.Fatalf("编号延续应分配 A0005: %v %+v", err, na)
279		}
280		if moved, _, err := s.relocateAsset("EQ-A", "三楼", "工位再调整"); err != nil || moved.Location != "三楼" {
281			t.Fatalf("还原后搬移应按原规则运行: %v %+v", err, moved)
282		}
283		mustSave(t, s)
284		if _, err := openStore(target); err != nil {
285			t.Fatalf("后续业务保存后台账仍须一致: %v", err)
286		}
287		// ticket 查询：有效附件文件可读，已撤销附件保持撤销显示（源已移走）。
288		var buf bytes.Buffer
289		if err := cmdTicket([]string{"--ticket-id", "T0002", "--data-dir", target}, &buf); err != nil {
290			t.Fatalf("ticket 查询失败: %v", err)
291		}
292		ticketOut := buf.String()
293		if !strings.Contains(ticketOut, "有效（文件可读）") {
294			t.Fatalf("移走源目录后有效附件应仍可读: %s", ticketOut)
295		}
296		if err := cmdHistory([]string{"--asset-id", "EQ-A", "--data-dir", target}, &buf); err != nil {
297			t.Fatalf("history 查询失败: %v", err)
298		}
299	}
300	
301	// 数组乱序、序号间隔、时间不递增的有效旧库同样可以打包，履历顺序、
302	// 报修地点等在还原后保持。
303	func TestMigrateExportUnorderedLegacyLedger(t *testing.T) {
304		fx := newMigrateFixture(t)
305		raw := readFileBytes(t, fx.srcDir)
306		var m map[string]any
307		if err := json.Unmarshal(raw, &m); err != nil {
308			t.Fatal(err)
309		}
310		evs := m["events"].([]any)
311		// 先按 seq 升序以便赋递减时间，再整体随机打乱数组存放。
312		sort.Slice(evs, func(i, j int) bool {
313			return int(evs[i].(map[string]any)["seq"].(float64)) < int(evs[j].(map[string]any)["seq"].(float64))
314		})
315		for i, e := range evs {
316			e.(map[string]any)["time"] = fmt.Sprintf("2026-12-31T23:59:%02dZ", len(evs)-i)
317		}
318		r := rand.New(rand.NewSource(42))
319		shuffle := func(key string) {
320			if v, ok := m[key].([]any); ok {
321				r.Shuffle(len(v), func(i, j int) { v[i], v[j] = v[j], v[i] })
322			}
323		}
324		for _, key := range []string{"events", "assets", "tickets", "attachments", "parts"} {
325			shuffle(key)
326		}
327		out, err := json.Marshal(m)
328		if err != nil {
329			t.Fatal(err)
330		}
331		if err := os.WriteFile(filepath.Join(fx.srcDir, dataFileName), out, 0o644); err != nil {
332			t.Fatal(err)
333		}
334		if _, err := openStore(fx.srcDir); err != nil {
335			t.Fatalf("乱序且时间不递增的旧库应仍为有效台账: %v", err)
336		}
337		pkg := filepath.Join(t.TempDir(), "pkg.zip")
338		if _, err := exportPackage(fx.srcDir, pkg, []string{"EQ-A", "EQ-B"}); err != nil {
339			t.Fatalf("乱序旧库应可打包: %v", err)
340		}
341		target := filepath.Join(t.TempDir(), "out")
342		if _, err := restorePackage(pkg, target); err != nil {
343			t.Fatalf("还原失败: %v", err)
344		}
345		s, err := openStore(target)
346		if err != nil {
347			t.Fatalf("还原后加载: %v", err)
348		}
349		evs2 := s.eventsOf("EQ-A")
350		for i := 1; i < len(evs2); i++ {
351			if evs2[i].Seq <= evs2[i-1].Seq {
352				t.Fatal("履历应按序号有序展示")
353			}
354		}
355		if t1 := s.findTicket("T0001"); t1 == nil || t1.ReportLocation != "一楼" {
356			t.Fatalf("报修地点应保持，得到 %+v", t1)
357		}
358		// 时间精度（此处为逆序的赋值时间）保持。
359		var sawNonMonotonic bool
360		for i := 1; i < len(evs2); i++ {
361			if evs2[i].Time.Before(evs2[i-1].Time) {
362				sawNonMonotonic = true
363			}
364		}
365		if !sawNonMonotonic {
366			t.Fatal("时间不递增的旧库时间在还原后应保持原样")
367		}
368	}
369	
370	// 导出失败路径：未知资产、资料缺失、源台账缺失、包路径已存在；任何失败
371	// 都不留下成品包或临时文件，源台账字节保持，恢复资料后可用原参数重试。
372	func TestMigrateExportFailures(t *testing.T) {
373		fx := newMigrateFixture(t)
374		work := t.TempDir()
375		srcBefore := readFileBytes(t, fx.srcDir)
376	
377		// 未知资产整次拒绝。
378		pkg := filepath.Join(work, "unknown.zip")
379		if _, err := exportPackage(fx.srcDir, pkg, []string{"EQ-A", "EQ-NOPE"}); err == nil {
380			t.Fatal("未知资产应拒绝打包")
381		}
382		if _, err := os.Lstat(pkg); !os.IsNotExist(err) {
383			t.Fatal("失败后不应留下包文件")
384		}
385		// 空资产列表在命令入口为参数错误（退出 2）。
386		var out, errOut bytes.Buffer
387		if code := run([]string{"export", "--data-dir", fx.srcDir, "--package", pkg}, &out, &errOut); code != 2 {
388			t.Fatalf("缺少 --asset-id 应退出 2，得到 %d", code)
389		}
390	
391		// 资料缺失：删除 A0003 指向的文件，错误须指出附件编号与原因。
392		s, err := openStore(fx.srcDir)
393		if err != nil {
394			t.Fatal(err)
395		}
396		missingPath := s.findAttachment("A0003").Path
397		if err := os.Remove(missingPath); err != nil {
398			t.Fatal(err)
399		}
400		pkg = filepath.Join(work, "missing.zip")
401		_, err = exportPackage(fx.srcDir, pkg, []string{"EQ-A", "EQ-B"})
402		if err == nil || !strings.Contains(err.Error(), "A0003") {
403			t.Fatalf("资料缺失应拒绝并指出附件编号 A0003，得到 %v", err)
404		}
405		if _, err := os.Lstat(pkg); !os.IsNotExist(err) {
406			t.Fatal("资料缺失不应留下成品包")
407		}
408		if entries, _ := os.ReadDir(work); len(entries) != 0 {
409			t.Fatalf("失败后不应留下临时文件，得到 %v", entries)
410		}
411	
412		// 资料成为目录：不是可读普通文件，同样整次拒绝并指出附件编号。
413		if err := os.WriteFile(missingPath, []byte("资料三内容"), 0o644); err != nil {
414			t.Fatal(err)
415		}
416		dirPath := s.findAttachment("A0004").Path
417		if err := os.Remove(dirPath); err != nil {
418			t.Fatal(err)
419		}
420		if err := os.Mkdir(dirPath, 0o755); err != nil {
421			t.Fatal(err)
422		}
423		if _, err := exportPackage(fx.srcDir, filepath.Join(work, "dir.zip"),
424			[]string{"EQ-B"}); err == nil || !strings.Contains(err.Error(), "A0004") {
425			t.Fatalf("资料为目录应拒绝并指出附件编号 A0004，得到 %v", err)
426		}
427		if err := os.Remove(dirPath); err != nil {
428			t.Fatal(err)
429		}
430	
431		// 只导出不引用缺失资料的资产可以成功。
432		if _, err := exportPackage(fx.srcDir, filepath.Join(work, "d.zip"), []string{"EQ-D"}); err != nil {
433			t.Fatalf("不引用缺失资料的资产应可导出: %v", err)
434		}
435	
436		// 源台账不存在（数据目录存在但无台账）不能当空库。
437		emptyDir := filepath.Join(work, "empty")
438		if err := os.MkdirAll(emptyDir, 0o755); err != nil {
439			t.Fatal(err)
440		}
