442			t.Fatal("缺少源台账应拒绝")
443		}
444	
445		// 恢复缺失资料后用原参数重试成功，证明失败未消耗任何东西。
446		if err := os.WriteFile(missingPath, []byte("资料三内容"), 0o644); err != nil {
447			t.Fatal(err)
448		}
449		if err := os.WriteFile(dirPath, []byte("资料四内容"), 0o644); err != nil {
450			t.Fatal(err)
451		}
452		if _, err := exportPackage(fx.srcDir, pkg, []string{"EQ-A", "EQ-B"}); err != nil {
453			t.Fatalf("恢复资料后应可用原参数重试成功: %v", err)
454		}
455	
456		// 已有包文件不得覆盖：原包字节保持。
457		existing := pkg
458		before, err := os.ReadFile(existing)
459		if err != nil {
460			t.Fatal(err)
461		}
462		if _, err := exportPackage(fx.srcDir, existing, []string{"EQ-D"}); err == nil {
463			t.Fatal("已有包文件不得覆盖")
