554	// 损坏包与非法成员：内容损坏、缺失/额外/重复成员、越界路径、目录与链接
555	// 成员、未知格式或版本均拒绝，且不创建目标目录、不在父目录留暂存。
556	func TestMigrateRestoreRejectsCorruptPackages(t *testing.T) {
557		fx := newMigrateFixture(t)
