563	
564		setManifestField := func(es []pkgEntry, key string, value any) []pkgEntry {
565			e := findEntry(es, migrateManifestName)
566			var mm map[string]any
567			if err := json.Unmarshal(e.data, &mm); err != nil {
568				t.Fatal(err)
569			}
570			mm[key] = value
571			b, err := json.Marshal(mm)
572			if err != nil {
573				t.Fatal(err)
574			}
575			e.data = b
576			return es
577		}
578	
579		cases := []struct {
580			name    string
581			mutate  func(entries []pkgEntry) []pkgEntry
582			wantErr string
583		}{
584			{"台账内容损坏", func(es []pkgEntry) []pkgEntry {
585				e := findEntry(es, migrateLedgerName)
586				b := append([]byte(nil), e.data...)
587				b[len(b)-20] ^= 0xFF
588				e.data = b
589				return es
