608			}, "重复"},
609			{"越界成员路径", func(es []pkgEntry) []pkgEntry {
610				return append(es, pkgEntry{name: "../evil", data: []byte("x")})
611			}, "越界"},
612			{"嵌套越界成员路径", func(es []pkgEntry) []pkgEntry {
