151	
152	func (e Event) toJSON() eventJSON {
153		return eventJSON{
154			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
155			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
156			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
157			NewContent: e.NewContent, OldContent: e.OldContent,
158			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
159			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
160			AttachmentID: e.AttachmentID, Path: e.Path,
161			// RFC3339Nano 保留小数秒精度；整秒时输出与 RFC3339 完全一致，
162			// 因此既有整秒台账的字节表示不变，而旧库中带小数秒的履历时间
163			// 在重新保存（含导入合并后的提交）时也不会被截断。
164			Time: e.Time.Format(time.RFC3339Nano),
165		}
166	}
167	
168	func (e eventJSON) toEvent() (Event, error) {
169		t, err := time.Parse(time.RFC3339, e.Time)
170		if err != nil {
171			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
172		}
173		return Event{
174			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
175			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
176			Due: e.Due, Done: e.Done, Interval: e.Interval, TargetSeq: e.TargetSeq,
177			NewContent: e.NewContent, OldContent: e.OldContent,
178			OldDue: e.OldDue, OldInterval: e.OldInterval, OldNextDue: e.OldNextDue,
179			PartID: e.PartID, Quantity: e.Quantity, WithdrawalID: e.WithdrawalID,
180			AttachmentID: e.AttachmentID, Path: e.Path,
181			Time: t,
182		}, nil
183	}
