185	// PartWithdrawal 为一笔备件领用记录，ID 即领用编号（同目录唯一、不复用）。
186	// 数量表示工单用量；Returned 为累计退回数量，净量 = Quantity - Returned。
187	// 工单关闭或取消后记录与净量保留，不清零。
188	type PartWithdrawal struct {
189		ID       string `json:"id"`
190		TicketID string `json:"ticket_id"`
191		AssetID  string `json:"asset_id"`
192		PartID   string `json:"part_id"`
193		Quantity int    `json:"quantity"`
194		Note     string `json:"note"`
195		Returned int    `json:"returned"`
196	}
197	
198	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
199	// 它既不是资产编号也不是工单编号。
200	type requestBinding struct {
201		RequestID   string `json:"request_id"`
202		AssetID     string `json:"asset_id"`
203		Description string `json:"description"`
204		TicketID    string `json:"ticket_id"`
205	}
206	
207	// Attachment 为工单本地资料附件的索引记录，ID 即附件编号（同目录唯一、不复用）。
208	// 只保存引用：Path 为登记时解析得到的绝对路径，工具不复制、不修改、不删除
209	// 资料文件本身。撤销后保留记录、路径、说明（Note）与撤销理由（RevokeReason），
210	// 已撤销编号不能恢复；工单终结不自动撤销附件。
211	type Attachment struct {
212		ID           string `json:"id"`
213		TicketID     string `json:"ticket_id"`
214		AssetID      string `json:"asset_id"`
215		Path         string `json:"path"`
216		Note         string `json:"note"`
217		Revoked      bool   `json:"revoked"`
218		RevokeReason string `json:"revoke_reason,omitempty"`
219	}
