221	// storeData 是一次成功写操作共同生效的完整业务数据。
222	type storeData struct {
223		Version       int               `json:"version"`
224		Assets        []*Asset          `json:"assets"`
225		Tickets       []*Ticket         `json:"tickets"`
226		Events        []Event           `json:"-"`
227		EventsJSON    []eventJSON       `json:"events"`
228		Requests      []requestBinding  `json:"requests"`
229		Plans         []*Plan           `json:"plans"`
230		Parts         []*PartWithdrawal `json:"parts"`
231		Attachments   []*Attachment     `json:"attachments"`
232		NextTicketSeq int               `json:"next_ticket_seq"`
233		NextPartSeq   int               `json:"next_part_seq"`
234		NextAttachSeq int               `json:"next_attach_seq"`
235	}
236	
237	type store struct {
238		dir  string
239		data *storeData
240		now  func() time.Time
241	}
242	
243	func newStoreData() *storeData {
244		return &storeData{
245			Version:       storeVersion,
246			Assets:        []*Asset{},
247			Tickets:       []*Ticket{},
248			Events:        []Event{},
249			EventsJSON:    []eventJSON{},
250			Requests:      []requestBinding{},
251			Plans:         []*Plan{},
252			Parts:         []*PartWithdrawal{},
253			Attachments:   []*Attachment{},
254			NextTicketSeq: 1,
255			NextPartSeq:   1,
256			NextAttachSeq: 1,
257		}
258	}
