260	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
261	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
262	func openStore(dir string) (*store, error) {
263		return loadStore(dir, true)
264	}
265	
266	// openSourceStore 以只读用途打开导入源数据目录：与 openStore 做同样的整库
267	// 一致性检查，但源台账必须已存在——不存在时报错，绝不能当空库初始化。
268	func openSourceStore(dir string) (*store, error) {
269		return loadStore(dir, false)
270	}
271	
272	func loadStore(dir string, allowMissing bool) (*store, error) {
273		path := filepath.Join(dir, dataFileName)
274		raw, err := os.ReadFile(path)
275		if err != nil {
276			if errors.Is(err, os.ErrNotExist) {
277				if allowMissing {
278					return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
279				}
280				return nil, fmt.Errorf("源数据文件 %s 不存在：源台账必须已存在，不能当空库处理", path)
281			}
282			return nil, fmt.Errorf("读取数据文件失败: %w", err)
283		}
284		if len(bytes.TrimSpace(raw)) == 0 {
285			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
286		}
287		var d storeData
288		if err := json.Unmarshal(raw, &d); err != nil {
289			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
290		}
291		if d.EventsJSON != nil {
292			d.Events = make([]Event, len(d.EventsJSON))
293			for i, ej := range d.EventsJSON {
294				ev, err := ej.toEvent()
295				if err != nil {
296					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
297				}
298				d.Events[i] = ev
299			}
300		}
301		// 无保养字段的有效旧库直接使用：缺省视为没有任何保养计划。
302		if d.Plans == nil {
303			d.Plans = []*Plan{}
304		}
305		// 无备件字段的有效旧库直接使用：缺省视为没有任何备件领用记录，
306		// 领用编号计数器从 1 开始。
307		if d.Parts == nil {
308			d.Parts = []*PartWithdrawal{}
309		}
310		if d.NextPartSeq == 0 && len(d.Parts) == 0 {
311			d.NextPartSeq = 1
312		}
313		// 无附件字段的有效旧库直接使用：缺省视为没有任何附件索引记录，
314		// 附件编号计数器从 1 开始。
315		if d.Attachments == nil {
316			d.Attachments = []*Attachment{}
317		}
318		if d.NextAttachSeq == 0 && len(d.Attachments) == 0 {
319			d.NextAttachSeq = 1
320		}
321		if err := validateData(&d); err != nil {
322			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
323		}
324		return &store{dir: dir, data: &d, now: time.Now}, nil
325	}
326	
327	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
328	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
329	func parseTicketSeq(id string) (int, bool) {
330		if !strings.HasPrefix(id, "T") {
331			return 0, false
332		}
333		n, err := strconv.Atoi(id[1:])
334		if err != nil || n < 1 {
335			return 0, false
336		}
337		if fmt.Sprintf("T%04d", n) != id {
338			return 0, false
339		}
340		return n, true
341	}
342	
343	// parsePartSeq 解析 P 加补零正整数序号形式的领用编号，返回序号。
344	// 编号必须与 fmt.Sprintf("P%04d", n)（n ≥ 1）完全一致，否则视为非法。
345	func parsePartSeq(id string) (int, bool) {
346		if !strings.HasPrefix(id, "P") {
347			return 0, false
348		}
349		n, err := strconv.Atoi(id[1:])
350		if err != nil || n < 1 {
351			return 0, false
352		}
353		if fmt.Sprintf("P%04d", n) != id {
354			return 0, false
355		}
356		return n, true
357	}
358	
359	// parseAttachSeq 解析 A 加补零正整数序号形式的附件编号，返回序号。
360	// 编号必须与 fmt.Sprintf("A%04d", n)（n ≥ 1）完全一致，否则视为非法。
361	func parseAttachSeq(id string) (int, bool) {
362		if !strings.HasPrefix(id, "A") {
363			return 0, false
364		}
365		n, err := strconv.Atoi(id[1:])
366		if err != nil || n < 1 {
367			return 0, false
368		}
369		if fmt.Sprintf("A%04d", n) != id {
370			return 0, false
371		}
372		return n, true
373	}
374	
375	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
376	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
377	// 不做任何修复：不补字段、不重编号、不删除记录。
378	func validateData(d *storeData) error {
379		if d.Version != storeVersion {
380			return fmt.Errorf("不支持的数据版本 %d", d.Version)
381		}
382		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil || d.Plans == nil || d.Parts == nil || d.Attachments == nil {
383			return errors.New("缺少必要的数据段")
384		}
385		assets := map[string]*Asset{}
386		for _, a := range d.Assets {
387			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
388				return errors.New("数据矛盾：存在字段不完整的资产记录")
389			}
390			if a.Status != statusAvailable && a.Status != statusRepairing && a.Status != statusDeactivated {
391				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
392			}
393			if assets[a.ID] != nil {
394				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
395			}
396			assets[a.ID] = a
397		}
398		tickets := map[string]*Ticket{}
399		maxTicketSeq := 0
400		for _, t := range d.Tickets {
401			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
402				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
403			}
404			n, ok := parseTicketSeq(t.ID)
405			if !ok {
406				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
407			}
408			if n > maxTicketSeq {
409				maxTicketSeq = n
410			}
411			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
412				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
413			}
414			if assets[t.AssetID] == nil {
415				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
416			}
417			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
418				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
419			}
420			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
421				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
422			}
423			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
424				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
425			}
426			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
427				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
428			}
429			if t.Assignee == "" {
430				if t.AssignedAt != "" || t.AssignNote != "" {
431					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
432				}
433			} else if t.AssignedAt == "" || t.AssignNote == "" {
434				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
435			}
436			if tickets[t.ID] != nil {
437				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
438			}
439			tickets[t.ID] = t
440		}
441		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
442		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
443			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
444				d.NextTicketSeq, maxTicketSeq)
445		}
446		// 备件领用记录：编号唯一且为 P 加补零正整数序号，归属存在的工单且资产归属
447		// 与工单一致，数量为正，累计退回在 [0, 原数量] 内；与履历的接续在下方按
448		// 履历序号重放时核对。
449		parts := map[string]*PartWithdrawal{}
450		maxPartSeq := 0
451		for _, p := range d.Parts {
452			if p == nil || p.ID == "" || p.TicketID == "" || p.AssetID == "" || p.PartID == "" || p.Note == "" {
453				return errors.New("数据矛盾：存在字段不完整的备件领用记录")
454			}
455			n, ok := parsePartSeq(p.ID)
456			if !ok {
457				return fmt.Errorf("计数器矛盾：领用编号 %q 不是 P 加补零正整数序号的形式", p.ID)
458			}
459			if n > maxPartSeq {
460				maxPartSeq = n
461			}
462			if p.Quantity < 1 {
463				return fmt.Errorf("数据矛盾：领用记录 %s 的数量 %d 不是正整数", p.ID, p.Quantity)
464			}
465			if p.Returned < 0 || p.Returned > p.Quantity {
466				return fmt.Errorf("备件数量矛盾：领用记录 %s 的累计退回 %d 超出原数量 %d", p.ID, p.Returned, p.Quantity)
467			}
468			t := tickets[p.TicketID]
469			if t == nil {
470				return fmt.Errorf("数据矛盾：领用记录 %s 引用了不存在的工单 %s", p.ID, p.TicketID)
471			}
472			if t.AssetID != p.AssetID {
473				return fmt.Errorf("数据矛盾：领用记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
474					p.ID, p.AssetID, t.ID, t.AssetID)
475			}
476			if parts[p.ID] != nil {
477				return fmt.Errorf("数据矛盾：领用编号 %s 重复", p.ID)
478			}
479			parts[p.ID] = p
480		}
481		// 下一领用序号必须为正并大于全部已用序号（允许有间隔）。
482		if d.NextPartSeq < 1 || d.NextPartSeq <= maxPartSeq {
483			return fmt.Errorf("计数器矛盾：下一领用序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
484				d.NextPartSeq, maxPartSeq)
485		}
486		// 附件索引记录：编号唯一且为 A 加补零正整数序号，归属存在的工单且资产归属
487		// 与工单一致，路径为绝对路径，说明非空；撤销状态与理由相互呼应。文件当前
488		// 是否可用不参与整库一致性校验；与履历的接续在下方按履历序号重放时核对。
489		attachments := map[string]*Attachment{}
490		maxAttachSeq := 0
491		for _, a := range d.Attachments {
492			if a == nil || a.ID == "" || a.TicketID == "" || a.AssetID == "" || a.Path == "" || a.Note == "" {
493				return errors.New("数据矛盾：存在字段不完整的附件记录")
494			}
495			n, ok := parseAttachSeq(a.ID)
496			if !ok {
497				return fmt.Errorf("计数器矛盾：附件编号 %q 不是 A 加补零正整数序号的形式", a.ID)
498			}
499			if n > maxAttachSeq {
500				maxAttachSeq = n
501			}
502			if !filepath.IsAbs(a.Path) {
503				return fmt.Errorf("数据矛盾：附件记录 %s 的路径 %q 不是绝对路径", a.ID, a.Path)
504			}
505			t := tickets[a.TicketID]
506			if t == nil {
507				return fmt.Errorf("数据矛盾：附件记录 %s 引用了不存在的工单 %s", a.ID, a.TicketID)
508			}
509			if t.AssetID != a.AssetID {
510				return fmt.Errorf("数据矛盾：附件记录 %s 的资产 %s 与工单 %s 归属的资产 %s 不一致",
511					a.ID, a.AssetID, t.ID, t.AssetID)
512			}
513			if a.Revoked && a.RevokeReason == "" {
514				return fmt.Errorf("状态矛盾：已撤销附件 %s 缺少撤销理由", a.ID)
515			}
516			if !a.Revoked && a.RevokeReason != "" {
517				return fmt.Errorf("状态矛盾：有效附件 %s 不应带有撤销理由", a.ID)
518			}
519			if attachments[a.ID] != nil {
520				return fmt.Errorf("数据矛盾：附件编号 %s 重复", a.ID)
521			}
522			attachments[a.ID] = a
523		}
524		// 下一附件序号必须为正并大于全部已用序号（允许有间隔）。
525		if d.NextAttachSeq < 1 || d.NextAttachSeq <= maxAttachSeq {
526			return fmt.Errorf("计数器矛盾：下一附件序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
527				d.NextAttachSeq, maxAttachSeq)
528		}
529		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
530		boundReq := map[string]bool{}
531		boundTicket := map[string]bool{}
532		for _, r := range d.Requests {
533			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
534				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
535			}
536			if boundReq[r.RequestID] {
537				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
538			}
539			boundReq[r.RequestID] = true
540			t := tickets[r.TicketID]
541			if t == nil {
542				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
543			}
544			if t.RequestID != r.RequestID {
545				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
546					r.TicketID, t.RequestID, r.RequestID)
547			}
548			if r.AssetID != t.AssetID || r.Description != t.Description {
549				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
550					r.RequestID, t.ID)
551			}
552			boundTicket[r.TicketID] = true
553		}
554		for _, t := range d.Tickets {
555			if !boundTicket[t.ID] {
556				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
557			}
558		}
559		// 状态：每项资产最多一张未关闭工单，有则必须为“维修中”；无未关闭工单时
560		// 资产可为“可用”或“停用”，停用与否由停用、恢复使用履历链决定，在下方
561		// 按履历序号重放时核对。
562		openCount := map[string]int{}
563		for _, t := range d.Tickets {
564			if t.Status == ticketOpen {
565				openCount[t.AssetID]++
566			}
567		}
568		for _, a := range d.Assets {
569			c := openCount[a.ID]
570			if c > 1 {
571				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
572			}
573			if c == 1 {
574				if a.Status != statusRepairing {
575					return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
576						a.ID, c, statusRepairing, a.Status)
577				}
578				continue
579			}
580			if a.Status != statusAvailable && a.Status != statusDeactivated {
581				return fmt.Errorf("状态矛盾：资产 %s 没有未关闭工单，状态应为 %s 或 %s，实际为 %s",
582					a.ID, statusAvailable, statusDeactivated, a.Status)
583			}
584		}
585		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
586		seenSeq := map[int]bool{}
587		reportSeq := map[string]int{}
588		closeSeq := map[string]int{}
589		cancelSeq := map[string]int{}
590		reportCount := map[string]int{}
591		closeCount := map[string]int{}
592		cancelCount := map[string]int{}
593		for i := range d.Events {
594			e := &d.Events[i]
595			if e.Seq < 1 {
596				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
597			}
598			if seenSeq[e.Seq] {
599				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
600			}
601			seenSeq[e.Seq] = true
602			if e.AssetID == "" || e.Kind == "" || e.Content == "" {
603				return errors.New("履历矛盾：存在字段不完整的履历记录")
604			}
605			if e.Kind == eventPlanCreate || e.Kind == eventPlanDone || e.Kind == eventPlanRevoke || e.Kind == eventPlanAdjust {
606				// 保养履历：不属于任何工单，不携带派工、备件或附件字段；日期与间隔在此
607				// 核对，建立、完成、撤销与调整链的接续在下方按序号重放时核对。
608				if e.TicketID != "" || e.From != "" || e.To != "" {
609					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号或派工人员字段", e.Seq, e.Kind)
610				}
611				if e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
612					e.AttachmentID != "" || e.Path != "" {
613					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件或附件字段", e.Seq, e.Kind)
614				}
615				if e.Kind != eventPlanAdjust &&
616					(e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "") {
617					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有方案调整字段", e.Seq, e.Kind)
618				}
619				if e.Kind == eventPlanAdjust {
620					// 调整履历：内容即调整理由（非空已检查）；Due/Interval 为新方案的
621					// 首次到期日与间隔天数，另携带原方案与调整前的下一到期日。
622					if e.Done != "" || e.TargetSeq != 0 {
623						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录不应带有完成日或目标完成履历序号", e.Seq)
624					}
625					if e.NewContent == "" {
626						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少新保养内容", e.Seq)
627					}
628					if _, err := parseDate(e.Due); err != nil {
629						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新首次到期日无效", e.Seq)
630					}
631					if e.Interval < 1 {
632						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录新间隔天数须为正整数", e.Seq)
633					}
634					if e.OldContent == "" {
635						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录缺少原保养内容", e.Seq)
636					}
637					if _, err := parseDate(e.OldDue); err != nil {
638						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原首次到期日无效", e.Seq)
639					}
640					if e.OldInterval < 1 {
641						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原间隔天数须为正整数", e.Seq)
642					}
643					if _, err := parseDate(e.OldNextDue); err != nil {
644						return fmt.Errorf("履历矛盾：履历序号 %d 的调整记录原下一到期日无效", e.Seq)
645					}
646					continue
647				}
648				if e.Kind == eventPlanRevoke {
649					// 撤销履历：内容即撤销理由（非空已检查），仅携带目标完成履历序号。
650					if e.Due != "" || e.Done != "" || e.Interval != 0 {
651						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录不应带有到期日、完成日或间隔天数", e.Seq)
652					}
653					if e.TargetSeq < 1 {
654						return fmt.Errorf("履历矛盾：履历序号 %d 的撤销记录目标完成履历序号须为正整数", e.Seq)
655					}
656					continue
657				}
658				if e.TargetSeq != 0 {
659					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有目标完成履历序号", e.Seq, e.Kind)
660				}
661				due, err := parseDate(e.Due)
662				if err != nil {
663					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录到期日无效", e.Seq, e.Kind)
664				}
665				if e.Kind == eventPlanCreate {
666					if e.Done != "" {
667						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录不应带有完成日", e.Seq)
668					}
669					if e.Interval < 1 {
670						return fmt.Errorf("履历矛盾：履历序号 %d 的建立记录间隔天数须为正整数", e.Seq)
671					}
672				} else {
673					if e.Interval != 0 {
674						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录不应带有间隔天数", e.Seq)
675					}
676					done, err := parseDate(e.Done)
677					if err != nil {
678						return fmt.Errorf("履历矛盾：履历序号 %d 的完成记录完成日无效", e.Seq)
679					}
680					if done < due {
681						return fmt.Errorf("履历矛盾：履历序号 %d 的完成日早于周期到期日", e.Seq)
682					}
683				}
684				continue
685			}
686			if e.Kind == eventDeactivate || e.Kind == eventReactivate {
687				// 停用/恢复使用为资产级履历：不属于任何工单，From/To 为原状态与新
688				// 状态，不携带派工、保养、备件或附件字段。转换是否接续（可用->停用、
689				// 停用->可用）在下方按履历序号重放时核对。
690				if e.TicketID != "" {
691					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有工单编号", e.Seq, e.Kind)
692				}
693				if e.From == "" || e.To == "" {
694					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少原状态或新状态", e.Seq, e.Kind)
695				}
696				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
697					e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" ||
698					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
699					e.AttachmentID != "" || e.Path != "" {
700					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有保养、备件或附件字段", e.Seq, e.Kind)
701				}
702				if assets[e.AssetID] == nil {
703					return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产", e.Seq)
704				}
705				continue
706			}
707			if e.Kind == eventRelocate {
708				// 位置变更为资产级履历：不属于任何工单，From/To 为原位置与新位置，
709				// 新位置非空且与原位置不同，不携带派工、保养、备件或附件字段。
710				// 位置链接续（原位置须等于当时位置）与最终位置一致性在下方按履历
711				// 序号重放时核对。
712				if e.TicketID != "" {
713					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录不应带有工单编号", e.Seq)
714				}
715				if e.From == "" || e.To == "" {
716					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录缺少原位置或新位置", e.Seq)
717				}
718				if e.From == e.To {
719					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录新位置与原位置相同", e.Seq)
720				}
721				if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
722					e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" ||
723					e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "" ||
724					e.AttachmentID != "" || e.Path != "" {
725					return fmt.Errorf("履历矛盾：履历序号 %d 的位置变更记录不应带有保养、备件或附件字段", e.Seq)
726				}
727				if assets[e.AssetID] == nil {
728					return fmt.Errorf("位置矛盾：履历序号 %d 的位置变更记录引用了不存在的资产", e.Seq)
729				}
730				continue
731			}
732			if e.TicketID == "" {
733				return errors.New("履历矛盾：存在字段不完整的履历记录")
734			}
735			if e.Due != "" || e.Done != "" || e.Interval != 0 || e.TargetSeq != 0 ||
736				e.NewContent != "" || e.OldContent != "" || e.OldDue != "" || e.OldInterval != 0 || e.OldNextDue != "" {
737				return fmt.Errorf("履历矛盾：履历序号 %d 的维修履历不应带有保养字段", e.Seq)
738			}
739			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
740				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
741			}
742			if e.Kind == eventAssign {
743				if e.To == "" {
744					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
745				}
746				if e.From == e.To {
747					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
748				}
749			}
750			// 附件字段仅附件履历携带；附件履历不携带备件字段。
751			if e.Kind != eventAttach && e.Kind != eventAttachRevoke && (e.AttachmentID != "" || e.Path != "") {
752				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有附件编号或路径", e.Seq, e.Kind)
753			}
754			if (e.Kind == eventAttach || e.Kind == eventAttachRevoke) &&
755				(e.PartID != "" || e.Quantity != 0 || e.WithdrawalID != "") {
756				return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录不应带有备件字段", e.Seq, e.Kind)
757			}
758			t := tickets[e.TicketID]
759			if t == nil || assets[e.AssetID] == nil {
760				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
761			}
762			if e.AssetID != t.AssetID {
763				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
764					e.Seq, e.AssetID, t.ID, t.AssetID)
765			}
766			switch e.Kind {
767			case eventReport:
768				if e.Content != t.Description {
769					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
770				}
771				reportCount[t.ID]++
772				reportSeq[t.ID] = e.Seq
773			case eventClose:
774				if e.Content != t.Result {
775					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
776				}
777				closeCount[t.ID]++
778				closeSeq[t.ID] = e.Seq
779			case eventCancel:
780				if e.Content != t.CancelReason {
781					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
782				}
783				cancelCount[t.ID]++
784				cancelSeq[t.ID] = e.Seq
785			case eventAssign:
786				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
787				// 在下方按序号重放时核对。
788			case eventPartWithdraw, eventPartReturn:
789				// 内容即领用说明或退回理由（非空已检查）；备件字段在此核对，
790				// 与领用记录的接续及累计退回在下方按序号重放时核对。
791				if e.PartID == "" || e.WithdrawalID == "" {
792					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少备件编号或领用编号", e.Seq, e.Kind)
793				}
794				if e.Quantity < 1 {
795					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录数量 %d 不是正整数", e.Seq, e.Kind, e.Quantity)
796				}
797				if _, ok := parsePartSeq(e.WithdrawalID); !ok {
798					return fmt.Errorf("履历矛盾：履历序号 %d 的领用编号 %q 不是 P 加补零正整数序号的形式",
799						e.Seq, e.WithdrawalID)
800				}
801			case eventAttach, eventAttachRevoke:
802				// 内容即附件说明或撤销理由（非空已检查）；附件字段在此核对，
803				// 与附件记录的接续及登记、撤销顺序在下方按序号重放时核对。
804				if e.AttachmentID == "" || e.Path == "" {
805					return fmt.Errorf("履历矛盾：履历序号 %d 的%s记录缺少附件编号或路径", e.Seq, e.Kind)
806				}
807				if _, ok := parseAttachSeq(e.AttachmentID); !ok {
808					return fmt.Errorf("履历矛盾：履历序号 %d 的附件编号 %q 不是 A 加补零正整数序号的形式",
809						e.Seq, e.AttachmentID)
810				}
811				if !filepath.IsAbs(e.Path) {
812					return fmt.Errorf("履历矛盾：履历序号 %d 的附件路径 %q 不是绝对路径", e.Seq, e.Path)
813				}
814			default:
815				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
816			}
817		}
818		for _, t := range d.Tickets {
819			if reportCount[t.ID] != 1 {
820				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
821			}
822			if t.Status == ticketClosed {
823				if closeCount[t.ID] != 1 {
824					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
825				}
826				if closeSeq[t.ID] <= reportSeq[t.ID] {
827					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
828						t.ID, closeSeq[t.ID], reportSeq[t.ID])
829				}
830			} else if closeCount[t.ID] != 0 {
831				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
832			}
833			if t.Status == ticketCancelled {
834				if cancelCount[t.ID] != 1 {
835					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
836				}
837				if cancelSeq[t.ID] <= reportSeq[t.ID] {
838					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
839						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
840				}
841			} else if cancelCount[t.ID] != 0 {
842				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
843			}
844		}
845		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
846		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
847		sorted := make([]Event, len(d.Events))
848		copy(sorted, d.Events)
849		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
850		// 位置链：每项资产的位置起点为最早一条位置变更履历（按全库序号）的原位置；
851		// 没有位置履历的资产以保存位置为起点。重放时原位置须接续当时位置、新位置
852		// 非空且不同，报修地点取报修履历序号当时的位置。
853		locationOrigin := map[string]string{}
854		relocateExists := map[string]bool{}
855		for _, a := range d.Assets {
856			locationOrigin[a.ID] = a.Location
857		}
858		minRelocateSeq := map[string]int{}
859		for _, e := range d.Events {
860			if e.Kind != eventRelocate {
861				continue
862			}
863			if !relocateExists[e.AssetID] || e.Seq < minRelocateSeq[e.AssetID] {
864				relocateExists[e.AssetID] = true
865				minRelocateSeq[e.AssetID] = e.Seq
866				locationOrigin[e.AssetID] = e.From
867			}
868		}
869		derivedLocation := map[string]string{}
870		for id, origin := range locationOrigin {
871			derivedLocation[id] = origin
872		}
873		ticketReportLocation := map[string]string{}
874		derivedTicket := map[string]string{}
875		derivedOpen := map[string]string{}
876		derivedDeactivated := map[string]bool{}
877		derivedAssignee := map[string]string{}
878		derivedNote := map[string]string{}
879		withdrawSeq := map[string]int{}
880		derivedReturned := map[string]int{}
881		attachRegSeq := map[string]int{}
882		attachRevokeSeq := map[string]int{}
883		for _, e := range sorted {
884			switch e.Kind {
885			case eventReport:
886				if derivedTicket[e.TicketID] != "" {
887					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
888				}
889				if prev := derivedOpen[e.AssetID]; prev != "" {
890					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
891						e.AssetID, prev, e.TicketID)
892				}
893				if derivedDeactivated[e.AssetID] {
894					return fmt.Errorf("履历矛盾：资产 %s 在停用期间产生了工单 %s 的报修",
895						e.AssetID, e.TicketID)
896				}
897				// 报修地点取该报修履历序号当时的资产位置：不能用当前地点、履历
898				// 时间或数组位置代替。
899				ticketReportLocation[e.TicketID] = derivedLocation[e.AssetID]
900				derivedTicket[e.TicketID] = ticketOpen
901				derivedOpen[e.AssetID] = e.TicketID
902			case eventRelocate:
903				// 原位置须接续当时位置；新位置非空且与原位置不同（非空与不同已在
904				// 上方逐条核对）。可用、维修中、停用资产均可变更，不影响工单占用。
905				if e.From != derivedLocation[e.AssetID] {
