908				}
909				derivedLocation[e.AssetID] = e.To
910			case eventDeactivate:
911				// 停用要求当时“可用”（无未关闭工单且未停用）；维修中（有未关闭
912				// 工单）的资产不能停用。From/To 须与实际转换一致。
913				if derivedOpen[e.AssetID] != "" {
914					return fmt.Errorf("履历矛盾：资产 %s 在存在未关闭工单时出现停用履历（序号 %d）",
915						e.AssetID, e.Seq)
