922						e.Seq, statusAvailable, statusDeactivated, e.From, e.To)
923				}
924				derivedDeactivated[e.AssetID] = true
925			case eventReactivate:
926				// 恢复使用只作用于停用资产；From/To 须与实际转换一致。
927				if !derivedDeactivated[e.AssetID] {
928					return fmt.Errorf("履历矛盾：资产 %s 未停用却出现恢复使用履历（序号 %d）", e.AssetID, e.Seq)
929				}
930				if derivedOpen[e.AssetID] != "" {
