932						e.AssetID, e.Seq)
933				}
934				if e.From != statusDeactivated || e.To != statusAvailable {
935					return fmt.Errorf("履历矛盾：恢复使用履历（序号 %d）原状态应为 %s、新状态应为 %s，实际为 %s -> %s",
936						e.Seq, statusDeactivated, statusAvailable, e.From, e.To)
937				}
938				delete(derivedDeactivated, e.AssetID)
939			case eventAssign:
940				if derivedTicket[e.TicketID] != ticketOpen {
941					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
942				}
943				if e.From != derivedAssignee[e.TicketID] {
