945						e.TicketID, e.Seq, e.From)
946				}
947				derivedAssignee[e.TicketID] = e.To
948				derivedNote[e.TicketID] = e.Content
949			case eventClose:
950				if derivedTicket[e.TicketID] != ticketOpen {
