952				}
953				derivedTicket[e.TicketID] = ticketClosed
954				delete(derivedOpen, e.AssetID)
955			case eventCancel:
956				if derivedTicket[e.TicketID] != ticketOpen {
957					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
958				}
