1011				// 履历与附件记录的业务字段必须一致。
1012				if derivedTicket[e.TicketID] == "" {
1013					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件登记履历（序号 %d）",
1014						e.TicketID, e.Seq)
1015				}
1016				a := attachments[e.AttachmentID]
1017				if a == nil {
1018					return fmt.Errorf("履历矛盾：附件登记履历（序号 %d）引用了不存在的附件记录 %s",
1019						e.Seq, e.AttachmentID)
1020				}
1021				if attachRegSeq[a.ID] != 0 {
