1026						e.Seq, a.ID)
1027				}
1028				attachRegSeq[a.ID] = e.Seq
1029			case eventAttachRevoke:
1030				// 撤销须在登记之后，且每个附件至多撤销一次；
1031				// 履历与附件记录的业务字段必须一致。
1032				if derivedTicket[e.TicketID] == "" {
1033					return fmt.Errorf("履历矛盾：工单 %s 在报修之前出现附件撤销履历（序号 %d）",
1034						e.TicketID, e.Seq)
1035				}
1036				a := attachments[e.AttachmentID]
1037				if a == nil {
1038					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）引用了不存在的附件记录 %s",
1039						e.Seq, e.AttachmentID)
1040				}
1041				if attachRegSeq[a.ID] == 0 {
1042					return fmt.Errorf("履历矛盾：附件撤销履历（序号 %d）出现在附件记录 %s 的登记履历之前",
1043						e.Seq, a.ID)
1044				}
1045				if attachRevokeSeq[a.ID] != 0 {
