1050						e.Seq, a.ID)
1051				}
1052				attachRevokeSeq[a.ID] = e.Seq
1053			}
1054		}
1055		for _, t := range d.Tickets {
1056			if derivedTicket[t.ID] != t.Status {
1057				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
1058					t.ID, derivedTicket[t.ID], t.Status)
1059			}
1060			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
1061			if derivedAssignee[t.ID] != t.Assignee {
