1070		for _, p := range d.Parts {
1071			if withdrawSeq[p.ID] == 0 {
1072				return fmt.Errorf("履历矛盾：领用记录 %s 缺少对应的领用履历", p.ID)
1073			}
1074			if derivedReturned[p.ID] != p.Returned {
1075				return fmt.Errorf("备件数量矛盾：按履历推出领用记录 %s 的累计退回为 %d，与保存的 %d 不符",
1076					p.ID, derivedReturned[p.ID], p.Returned)
1077			}
1078		}
1079		// 每条附件记录恰有一条登记履历、至多一条撤销履历；记录的撤销状态须与
1080		// 是否存在撤销履历一致。
1081		for _, a := range d.Attachments {
1082			if attachRegSeq[a.ID] == 0 {
1083				return fmt.Errorf("履历矛盾：附件记录 %s 缺少对应的登记履历", a.ID)
1084			}
1085			if revoked := attachRevokeSeq[a.ID] != 0; revoked != a.Revoked {
