1110		// 缺少该字段的有效旧库工单不补写，查询时现场追溯（已保证起点非空）。
1111		for _, t := range d.Tickets {
1112			got := ticketReportLocation[t.ID]
1113			if t.ReportLocation != "" && t.ReportLocation != got {
