1120		for _, p := range d.Plans {
1121			if p == nil || p.AssetID == "" || p.Content == "" {
1122				return errors.New("数据矛盾：存在字段不完整的保养计划")
1123			}
1124			if assets[p.AssetID] == nil {
1125				return fmt.Errorf("数据矛盾：保养计划引用了不存在的资产 %s", p.AssetID)
1126			}
1127			if plans[p.AssetID] != nil {
