1158			}
1159			if err := core.apply(e); err != nil {
1160				return maintValidateError(err)
1161			}
1162		}
1163		for _, p := range d.Plans {
1164			content, firstDue, interval, nextDue, created := core.derived(p.AssetID)
1165			if !created {
1166				return fmt.Errorf("履历矛盾：资产 %s 的保养计划应有恰一条建立履历，实际没有", p.AssetID)
1167			}
1168			if content != p.Content || firstDue != p.FirstDue || interval != p.IntervalDays {
