1170					p.AssetID, content, firstDue, interval,
1171					p.Content, p.FirstDue, p.IntervalDays)
1172			}
1173			if nextDue != p.NextDue {
1174				return fmt.Errorf("履历矛盾：按履历推出资产 %s 的下一到期日为 %s，与保存的 %s 不符",
1175					p.AssetID, nextDue, p.NextDue)
1176			}
1177		}
1178		return nil
1179	}
