1181	// maintValidateError 把保养规则核心返回的规则冲突包装为台账校验场景的错误
1182	// （指明“履历矛盾”类别）；调用方拒绝查询与写入并保留原文件。
1183	func maintValidateError(err error) error {
1184		var re *maintRuleError
1185		if !errors.As(err, &re) {
1186			return err
1187		}
1188		switch re.code {
1189		case ruleDuplicateCreate:
1190			return fmt.Errorf("履历矛盾：资产 %s 有多条保养建立履历", re.assetID)
1191		case ruleBeforeCreate:
1192			return fmt.Errorf("履历矛盾：资产 %s 的%s履历（序号 %d）出现在建立履历之前",
1193				re.assetID, re.kind, re.seq)
1194		case ruleAdjustScheme:
1195			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原方案与资产 %s 当时的方案不符",
1196				re.seq, re.assetID)
1197		case ruleAdjustNextDue:
1198			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）记录的原下一到期日 %s 与当时的下一到期日 %s 不符",
1199				re.seq, re.dateA, re.dateB)
1200		case ruleAdjustFirstDue:
1201			return fmt.Errorf("履历矛盾：保养调整履历（序号 %d）的新首次到期日 %s 未严格晚于未撤销完成（序号 %d）的实际完成日 %s",
1202				re.seq, re.dateA, re.doneSeq, re.dateB)
1203		case ruleRevokeOldSegment:
1204			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 属于资产 %s 调整前的旧方案段，旧段完成不能再撤销",
1205				re.seq, re.target, re.assetID)
1206		case ruleRevokeUnknown:
1207			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是资产 %s 先前的完成履历",
1208				re.seq, re.target, re.assetID)
1209		case ruleRevokeDuplicate:
1210			return fmt.Errorf("履历矛盾：完成履历序号 %d 被重复撤销（撤销履历序号 %d）", re.target, re.seq)
1211		case ruleRevokeNotLatest:
1212			return fmt.Errorf("履历矛盾：保养撤销履历（序号 %d）的目标序号 %d 不是当时最新的有效完成（序号 %d）",
1213				re.seq, re.target, re.latest)
1214		case ruleDoneDeactivated:
1215			return fmt.Errorf("履历矛盾：资产 %s 在停用期间出现保养完成履历（序号 %d）", re.assetID, re.seq)
1216		case ruleDueMismatch:
1217			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）周期到期日 %s 与当前下一到期日 %s 不接续",
1218				re.assetID, re.seq, re.dateA, re.dateB)
1219		case ruleDoneBeforeDue:
1220			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）完成日 %s 早于周期到期日 %s",
1221				re.assetID, re.seq, re.dateA, re.dateB)
1222		case ruleNextOverflow:
1223			return fmt.Errorf("履历矛盾：资产 %s 的保养完成履历（序号 %d）无法推出日期范围内的下一到期日",
1224				re.assetID, re.seq)
1225		}
1226		return err
1227	}
1228	
1229	// save 将全部业务数据一次性原子写入：先写同目录临时文件，fsync 后 rename
1230	// 覆盖正式文件。写入前先校验待提交数据的一致性；校验或读写失败时原文件
1231	// 保持不变，不留下部分业务变化。
1232	func (s *store) save() error {
1233		s.data.EventsJSON = make([]eventJSON, len(s.data.Events))
1234		for i, e := range s.data.Events {
1235			s.data.EventsJSON[i] = e.toJSON()
1236		}
1237		if err := validateData(s.data); err != nil {
1238			return fmt.Errorf("待保存数据未通过一致性检查：%w（未写入任何数据）", err)
1239		}
1240		var buf bytes.Buffer
1241		enc := json.NewEncoder(&buf)
1242		enc.SetIndent("", "  ")
1243		if err := enc.Encode(s.data); err != nil {
1244			return fmt.Errorf("编码数据失败: %w", err)
1245		}
1246		if err := os.MkdirAll(s.dir, 0o755); err != nil {
1247			return fmt.Errorf("创建数据目录失败: %w", err)
1248		}
1249		path := filepath.Join(s.dir, dataFileName)
1250		tmp, err := os.CreateTemp(s.dir, ".caretrack-*.tmp")
1251		if err != nil {
1252			return fmt.Errorf("创建临时数据文件失败: %w", err)
1253		}
1254		tmpName := tmp.Name()
1255		abort := func(err error) error {
1256			_ = tmp.Close()
1257			_ = os.Remove(tmpName)
1258			return err
1259		}
1260		if _, err := tmp.Write(buf.Bytes()); err != nil {
1261			abort(nil)
1262			return fmt.Errorf("写入数据失败: %w", err)
1263		}
1264		if err := tmp.Sync(); err != nil {
1265			abort(nil)
1266			return fmt.Errorf("写入数据失败: %w", err)
1267		}
1268		if err := tmp.Close(); err != nil {
1269			_ = os.Remove(tmpName)
1270			return fmt.Errorf("写入数据失败: %w", err)
1271		}
1272		if err := os.Rename(tmpName, path); err != nil {
1273			_ = os.Remove(tmpName)
1274			return fmt.Errorf("保存数据失败: %w", err)
1275		}
1276		return nil
1277	}
1278	
1279	func (s *store) findAsset(id string) *Asset {
1280		for _, a := range s.data.Assets {
1281			if a.ID == id {
1282				return a
1283			}
1284		}
1285		return nil
1286	}
1287	
1288	func (s *store) findTicket(id string) *Ticket {
1289		for _, t := range s.data.Tickets {
1290			if t.ID == id {
1291				return t
1292			}
1293		}
1294		return nil
1295	}
1296	
1297	func (s *store) findRequest(requestID string) *requestBinding {
1298		for i := range s.data.Requests {
1299			if s.data.Requests[i].RequestID == requestID {
1300				return &s.data.Requests[i]
1301			}
1302		}
1303		return nil
1304	}
1305	
1306	func (s *store) openTicketOf(assetID string) *Ticket {
1307		for _, t := range s.data.Tickets {
1308			if t.AssetID == assetID && t.Status == ticketOpen {
1309				return t
1310			}
1311		}
1312		return nil
1313	}
1314	
1315	func (s *store) eventsOf(assetID string) []Event {
1316		out := make([]Event, 0)
1317		for _, e := range s.data.Events {
1318			if e.AssetID == assetID {
1319				out = append(out, e)
1320			}
1321		}
1322		sort.SliceStable(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
1323		return out
1324	}
1325	
1326	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
1327	func (s *store) nextEventSeq() (int, error) {
1328		maxSeq := 0
1329		for _, e := range s.data.Events {
1330			if e.Seq > maxSeq {
1331				maxSeq = e.Seq
1332			}
1333		}
1334		if maxSeq == math.MaxInt {
1335			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
1336		}
1337		return maxSeq + 1, nil
1338	}
1339	
1340	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
1341	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
1342	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
1343		s.data.Events = append(s.data.Events, Event{
1344			Seq:      seq,
1345			AssetID:  assetID,
1346			TicketID: ticketID,
1347			Kind:     kind,
1348			Content:  content,
1349			From:     from,
1350			To:       to,
1351			Time:     s.now(),
1352		})
1353	}
1354	
1355	func (s *store) registerAsset(id, name, location string) (*Asset, error) {
1356		if s.findAsset(id) != nil {
1357			return nil, fmt.Errorf("%w: 资产编号 %q 已存在", errConflict, id)
1358		}
1359		a := &Asset{ID: id, Name: name, Location: location, Status: statusAvailable}
1360		s.data.Assets = append(s.data.Assets, a)
1361		return a, nil
1362	}
1363	
1364	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
1365	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
1366	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
1367		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
1368		// 资产或描述不同 => 拒绝。
1369		if r := s.findRequest(requestID); r != nil {
1370			if r.AssetID != assetID || r.Description != description {
1371				return nil, false, fmt.Errorf(
1372					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
1373					errConflict, requestID, r.AssetID)
1374			}
1375			t := s.findTicket(r.TicketID)
1376			if t == nil {
1377				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
1378			}
1379			return t, true, nil
1380		}
1381	
1382		asset := s.findAsset(assetID)
1383		if asset == nil {
1384			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
1385		}
1386		if asset.Status == statusDeactivated {
1387			// 停用期间拒绝新报修，也不绑定新请求标识；恢复使用后可用同一标识重试。
1388			return nil, false, fmt.Errorf("%w: 资产 %s 已停用，不能报修", errConflict, assetID)
1389		}
1390		if t := s.openTicketOf(assetID); t != nil {
1391			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
1392		}
1393		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
1394		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
1395		seq := s.data.NextTicketSeq
1396		if seq < 1 || seq == math.MaxInt {
1397			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
1398		}
1399		eventSeq, err := s.nextEventSeq()
1400		if err != nil {
1401			return nil, false, err
1402		}
1403		t := &Ticket{
1404			ID:          fmt.Sprintf("T%04d", seq),
1405			AssetID:     assetID,
1406			Description: description,
1407			RequestID:   requestID,
1408			Status:      ticketOpen,
1409			CreatedAt:   s.now().Format(time.RFC3339),
1410			// 报修地点在报修时按当时资产位置确定；之后位置变更不改写本字段，
1411			// 由加载/保存校验保证它与按报修履历序号追溯的位置一致。
1412			ReportLocation: asset.Location,
1413		}
1414		s.data.NextTicketSeq = seq + 1
1415		s.data.Tickets = append(s.data.Tickets, t)
1416		s.data.Requests = append(s.data.Requests, requestBinding{
1417			RequestID:   requestID,
1418			AssetID:     assetID,
1419			Description: description,
1420			TicketID:    t.ID,
1421		})
1422		asset.Status = statusRepairing
1423		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
1424		return t, false, nil
1425	}
1426	
1427	// closeTicket 关闭未关闭工单并把资产恢复为可用。
1428	// 失败路径不修改任何业务数据。
1429	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
1430		t := s.findTicket(ticketID)
1431		if t == nil {
1432			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1433		}
1434		if t.Status == ticketCancelled {
1435			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
1436		}
1437		if t.Status != ticketOpen {
1438			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
1439		}
1440		asset := s.findAsset(t.AssetID)
1441		if asset == nil {
1442			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1443		}
1444		eventSeq, err := s.nextEventSeq()
1445		if err != nil {
1446			return nil, nil, err
1447		}
1448		t.Status = ticketClosed
1449		t.Result = result
1450		t.ClosedAt = s.now().Format(time.RFC3339)
1451		asset.Status = statusAvailable
1452		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
1453		return t, asset, nil
1454	}
1455	
1456	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
1457	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
1458	// 失败路径不修改任何业务数据。
1459	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
1460		t := s.findTicket(ticketID)
1461		if t == nil {
1462			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1463		}
1464		if t.Status == ticketCancelled {
1465			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
1466		}
1467		if t.Status == ticketClosed {
1468			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
1469		}
1470		asset := s.findAsset(t.AssetID)
1471		if asset == nil {
1472			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
1473		}
1474		eventSeq, err := s.nextEventSeq()
1475		if err != nil {
1476			return nil, nil, err
1477		}
1478		t.Status = ticketCancelled
1479		t.CancelReason = reason
1480		t.CancelledAt = s.now().Format(time.RFC3339)
1481		asset.Status = statusAvailable
1482		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
1483		return t, asset, nil
1484	}
1485	
1486	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
1487	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
1488	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
1489	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
1490	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
1491	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
1492		t := s.findTicket(ticketID)
1493		if t == nil {
1494			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
1495		}
1496		if t.Status == ticketClosed {
1497			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
1498		}
1499		if t.Status == ticketCancelled {
1500			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
1501		}
1502		if assignee == "" {
1503			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
1504		}
1505		if note == "" {
1506			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
1507		}
1508		if t.Assignee == assignee {
1509			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
1510				errConflict, ticketID, assignee)
1511		}
1512		eventSeq, err := s.nextEventSeq()
1513		if err != nil {
1514			return nil, err
1515		}
1516		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
1517		t.Assignee = assignee
1518		t.AssignedAt = s.now().Format(time.RFC3339)
1519		t.AssignNote = note
1520		return t, nil
1521	}
1522

